/* [acct2-bro] Big Red One port, phase 1: the logging behind the stand-ins (generated by tools/bro_decomp/ngl_stubs.py
 * from bro/config/stand_in_functions.tsv): NGL's functions, and the Direct3D and DirectSound functions the game calls
 * from outside NGL.
 *
 * Each stand-in calls ngl_log_call() with its arguments. What gets printed is set by the BRO_NGL_LOG environment
 * variable:
 *   0  nothing
 *   1  (default) the first few calls of each function with their arguments, and every 300 frames a count of the
 *      calls each function got per frame
 *   2  every call
 * A frame ends at nglEndFrame. */
#pragma once
#include <stdint.h>
#include "ngl_stand_ins_ids.h"

void ngl_log_call(int id, const char *name, int nargs,
                  uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3, uint32_t a4, uint32_t a5);

/* For stand-ins whose real function returns a pointer: a zeroed 4 KB block of guest memory, one per function, made
 * on its first call and then always the same. */
uint32_t ngl_stand_in_block(int id);

/* For the Lock functions, whose callers write vertices, indices or pixels into what they get back: one shared 1 MB
 * guest buffer. What is written there is thrown away; nothing is drawn in phase 1. */
uint32_t ngl_stand_in_scratch(void);
